/* job_input_goods -- shipped at 1018:4b88, 137 bytes.
 *
 * The goods a building job consumes, written through `goods`; returns the count.
 *
 * HAND-CORRECTED, and deliberately not regenerated by tools/port.py: the reconstruction
 * it would come from has jobs 0x14 and 0x15 the wrong way round. The shipped code is a
 * jump table at SEG4:0x4c05 indexed by (job - 0x13), and its entries are
 *
 *     0x13 -> 0x4bf9 (nothing)      0x16 -> 0x4bc8 (goods 8)
 *     0x14 -> 0x4bb7 (goods 0xe)    0x17 -> 0x4bd9 (goods 0xf, then 8)
 *     0x15 -> 0x4ba6 (goods 0xf)    0x18 -> 0x4bf9 (nothing)
 *
 * so 0x14 consumes 0xe and 0x15 consumes 0xf. The differential measured exactly that and
 * disagreed with the port on those two jobs and no others. docs/findings/ has the whole
 * argument, including why the byte match did not catch it.
 *
 * The cases are written here in the order the shipped arms appear, which is the order the
 * original source must have had them in. Order does not affect behaviour; it is here so
 * the next person can line this up against the disassembly.
 */
#include "col/globals.h"

col_i16 job_input_goods(col_i16 *goods, col_i16 job)
{
    col_i16 n = 0;

    switch (job) {
    case 0x15:
        goods[n] = 0xf;
        n++;
        break;
    case 0x14:
        goods[n] = 0xe;
        n++;
        break;
    case 0x16:
        goods[n] = 8;
        n++;
        break;
    case 0x17:
        goods[n] = 0xf;
        n++;
        goods[n] = 8;
        n++;
        break;
    case 0x13:
    case 0x18:
        break;
    }
    return n;
}
